{
  "requirement_definitions": [
    {
      "id": "DMSR-5048",
      "title": "Simulated Data",
      "text": "The DMS shall provide the ability to inject artiﬁcial or simulated data into data products to assess the functional and temporal performance of the production processing software."
    },
    {
      "id": "DMSR-4919",
      "title": "Pre-cursor, and Real Data",
      "text": "The DMS shall provide for the ability to process data from other electronic, pixel-oriented astronomical imaging cameras."
    },
    {
      "id": "DMSR-4749",
      "title": "Image Diﬀerencing",
      "text": "The DMS shall provide software to perform image diﬀerencing, generating Diﬀerence Exposures from the comparison of single exposures and/or coadded images."
    },
    {
      "id": "DMSR-8783",
      "title": "Provide Source Detection Software",
      "text": "The DMS shall provide software for the detection of sources in a calibrated image, which may be a Diﬀerence Image or a Co-Add image."
    },
    {
      "id": "DMSR-2737",
      "title": "Provide Calibrated Photometry",
      "text": "The DMS shall provide calibrated photometry in each observed passband for all measured entities (e.g., DIASources, Sources, Objects), measuring the AB magnitude of the equivalent ﬂat-SED source, above the atmosphere. Fluxes, possibly in jansky, shall be calculated for all measured entities."
    },
    {
      "id": "DMSR-4926",
      "title": "Provide Astrometric Model",
      "text": "An astrometric model shall be provided for every Object and DIAObject which speciﬁes at least the proper motion and parallax, and the estimated uncertainties on these quantities."
    },
    {
      "id": "DMSR-5837",
      "title": "Provide Beam Projector Coordinate Calculation Software",
      "text": "The DMS shall provide software to represent the coordinate transformations relating the collimated beam projector position and telescope pupil position to the illumination position on the telescope optical elements and focal plane."
    },
    {
      "id": "DMSR-3610",
      "title": "Enable a Range of Shape Measurement Approaches",
      "text": "The DMS shall provide for the use of a variety of shape models on multiple kinds of input data to measure sources: measurement on coadds; measurement on coadds using information (e.g., PSFs) extracted from the individual exposures; measurement based on all the information from the individual Exposures simultaneously."
    }
  ],
  "allocation_entries": []
}
